"""A tool-using assistant: two tools defined with Pydantic, inputs validated before they run, and the
reason-act-observe loop that sends tool results back until the model answers.

Offline it runs against ScriptedModel, which replays a conversation written for this lab and checks that
your loop sends tool results back correctly. With ANTHROPIC_API_KEY and CLAUDE_MODEL set, run
`python react_loop.py --live` to use the real model.
"""

import json
import sys
from types import SimpleNamespace as NS
from typing import Literal

from pydantic import BaseModel, Field, ValidationError

from grounded import retrieve

SYSTEM = ("You help members of Lotus Lane Co-working with rooms and rules. Use search_policies for rules and "
          "check_room before saying a room is free. Answer briefly.")


class SearchPolicies(BaseModel):
    """Search Lotus Lane's policies. Use it for any question about rules, hours, plans, rooms, guests or refunds."""
    query: str = Field(description="What to look for, in a few words")
    k: int = Field(default=3, ge=1, le=5, description="How many policies to return")


class CheckRoom(BaseModel):
    """Check whether a meeting room is free. Use it before telling a member that a room is available."""
    room: Literal["Lotus", "Sen", "Bamboo"]
    day: Literal["Mon", "Tue", "Wed", "Thu", "Fri", "Sat"]
    start: str = Field(pattern=r"^([01]\d|2[0-3]):[0-5]\d$", description="Start time, 24-hour HH:MM")
    hours: float = Field(gt=0, le=4, description="Length of the booking in hours, at most 4")


SEATS = {"Lotus": 8, "Sen": 4, "Bamboo": 12}
BOOKINGS = {("Sen", "Mon"): [("13:00", "15:00")], ("Lotus", "Mon"): [("09:00", "11:00")]}


def minutes(hhmm):
    h, m = hhmm.split(":")
    return int(h) * 60 + int(m)


def search_policies(args):
    return [{"id": p["id"], "text": p["text"]} for score, p in retrieve(args.query, args.k) if score > 0]


def check_room(args):
    start = minutes(args.start)
    end = start + round(args.hours * 60)
    clash = [f"{a}-{b}" for a, b in BOOKINGS.get((args.room, args.day), []) if minutes(a) < end and start < minutes(b)]
    return {"room": args.room, "seats": SEATS[args.room], "day": args.day, "start": args.start,
            "end": f"{end // 60:02d}:{end % 60:02d}", "available": not clash, "clashes_with": clash}


TOOLS = {"search_policies": (SearchPolicies, search_policies), "check_room": (CheckRoom, check_room)}
TOOL_DEFINITIONS = [{"name": name, "description": model.__doc__, "input_schema": model.model_json_schema()}
                    for name, (model, _) in TOOLS.items()]


def run_tool(name, tool_input):
    """Validate the input against the tool's model, then run it. Returns (result text, is_error)."""
    if name not in TOOLS:
        return f"Unknown tool {name}", True
    model, function = TOOLS[name]
    # TODO 3: validate tool_input with model.model_validate(). If it raises ValidationError, return one
    #         "field: message" string per error, joined with "; ", and True. Otherwise run the function on
    #         the validated arguments and return json.dumps() of its result and False.
    raise NotImplementedError


def summarise(name, output):
    """A short version of a tool's result for the trace."""
    data = json.loads(output)
    if name == "search_policies":
        return ", ".join(d["id"] for d in data) or "nothing found"
    return f"available={data['available']} seats={data['seats']} clashes_with={data['clashes_with']}"


def run_agent(question, create, max_turns=6):
    """The loop: ask, run any tools the reply asks for, send their results back, repeat until an answer."""
    messages = [{"role": "user", "content": question}]
    calls = errors = 0
    for turn in range(1, max_turns + 1):
        reply = create(system=SYSTEM, tools=TOOL_DEFINITIONS, messages=messages)
        # TODO 4: add the reply to messages as an assistant turn (its whole content, tool_use blocks included).
        if reply.stop_reason != "tool_use":
            answer = "".join(b.text for b in reply.content if b.type == "text")
            print(f"Answer: {answer}")
            print(f"Model turns: {turn}, tool calls: {calls}, tool errors: {errors}")
            return answer
        # TODO 5: for every tool_use block in the reply, run it with run_tool(), count it (and any error),
        #         print a trace line like the one below, and collect a tool_result block:
        #         {"type": "tool_result", "tool_use_id": block.id, "content": output, "is_error": is_error}
        #         print(f"turn {turn}: {block.name} {json.dumps(block.input)} -> {shown}")
        #         where shown is "ERROR " + output for an error, or summarise(block.name, output).
        # TODO 6: send all the results back together, as one user message.
    print(f"Stopped after {max_turns} turns without an answer")
    return None


def tool_use(id_, name, tool_input):
    return NS(type="tool_use", id=id_, name=name, input=tool_input)


class ScriptedModel:
    """Replays a conversation written for this lab, and checks each tool result answers the right call."""

    TURNS = [
        NS(stop_reason="tool_use", content=[
            NS(type="text", text="Let me check the room rules first."),
            tool_use("call_1", "search_policies", {"query": "meeting room seats booking"})]),
        NS(stop_reason="tool_use", content=[
            tool_use("call_2", "check_room", {"room": "Sen", "day": "Monday", "start": "14:00", "hours": 3})]),
        NS(stop_reason="tool_use", content=[
            tool_use("call_3", "check_room", {"room": "Sen", "day": "Mon", "start": "14:00", "hours": 3}),
            tool_use("call_4", "check_room", {"room": "Lotus", "day": "Mon", "start": "14:00", "hours": 3})]),
        NS(stop_reason="end_turn", content=[NS(type="text", text=(
            "Sen seats only 4 and is booked from 13:00 to 15:00 on Monday, so it won't work for 5 people. "
            "Lotus seats 8 and is free on Monday from 14:00 to 17:00: you can book it in the member app."))]),
    ]

    def __init__(self):
        self.turn = 0

    def create(self, system, tools, messages):
        if self.turn > 0:
            if len(messages) < 2 or messages[-2]["role"] != "assistant":
                raise RuntimeError("the model's last reply is missing: append it as an assistant turn first")
            asked = {b.id for b in self.TURNS[self.turn - 1].content if b.type == "tool_use"}
            last = messages[-1]
            results = last["content"] if last["role"] == "user" and isinstance(last["content"], list) else []
            answered = {r.get("tool_use_id") for r in results if isinstance(r, dict) and r.get("type") == "tool_result"}
            if asked != answered:
                raise RuntimeError(f"tool results answer {sorted(answered)}, but the model asked for {sorted(asked)}")
        reply = self.TURNS[self.turn]
        self.turn += 1
        return reply


def live_create():
    """The only function that talks to the API: returns a create() with the same signature as the script's."""
    import os

    import anthropic

    client = anthropic.Anthropic()
    return lambda **kwargs: client.messages.create(model=os.environ["CLAUDE_MODEL"], max_tokens=1024, **kwargs)


def main():
    question = "Can I book the Sen room on Monday from 14:00 for 3 hours? There will be 5 of us."
    print(f"Q: {question}")
    create = live_create() if "--live" in sys.argv else ScriptedModel().create
    run_agent(question, create)


if __name__ == "__main__":
    main()
